description:
{
  "image_category": "MARKING_AND_SIGNAL",
  "summary": "Hình ảnh minh họa bố trí các loại vạch kẻ đường (vạch dừng xe, vạch nhường đường, vạch đi bộ qua đường) tại nút giao thông có đèn tín hiệu và vạch người đi bộ, phục vụ cho việc tìm kiếm và áp dụng đúng quy chuẩn QCVN 41:2024/BGTVT.",
  "items": [
    {
      "identifier": "Vạch dừng xe (Vạch 7.1)",
      "visual_or_geometric_features": "Vạch liền nét màu trắng, kẻ ngang toàn bộ bề rộng đường của hướng xe chạy, đặt trước vạch người đi bộ qua đường.",
      "meaning_or_specification": "Dùng để xác định vị trí dừng xe để chờ tín hiệu cho phép đi tiếp (đèn đỏ hoặc biển R.122). Bề rộng vạch chọn 20cm, 30cm hoặc 40cm tùy cấp đường và lưu lượng."
    },
    {
      "identifier": "Vạch nhường đường (Vạch 7.2)",
      "visual_or_geometric_features": "Vạch đôi nét đứt màu trắng, kẻ ngang trên toàn bộ bề rộng đường của hướng xe chạy.",
      "meaning_or_specification": "Báo hiệu cho xe phải đi chậm hoặc dừng lại để nhường đường cho các phương tiện trên các hướng giao thông khác được di chuyển trước. Thường dùng kết hợp với biển W.208."
    },
    {
      "identifier": "Vạch đi bộ qua đường (Vạch 7.3)",
      "visual_or_geometric_features": "Các đường vạch đậm liền song song màu trắng (dạng ngựa vằn), cắt ngang đường tại vị trí dành cho người đi bộ.",
      "meaning_or_specification": "Xác định phạm vi phần đường dành cho người đi bộ cắt qua đường. Chiều rộng nhỏ nhất không được nhỏ hơn 3m. Trước vạch này cần bố trí vạch dừng xe."
    },
    {
      "identifier": "Vạch chỉ dẫn sắp đến chỗ có bố trí vạch đi bộ qua đường (Vạch 7.6)",
      "visual_or_geometric_features": "Vạch có dạng hình thoi màu trắng, bố trí trên đường để báo hiệu sắp đến chỗ có vạch đi bộ.",
      "meaning_or_specification": "Sử dụng để báo hiệu sắp đến chỗ có bố trí vạch đi bộ qua đường, đặc biệt ở giữa đoạn đường nối hai nút giao, cảnh báo người lái xe phải nhường đường."
    }
  ]
}
